import { NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth/next"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    console.log(" Début de la création de proposition")

    const session = await getServerSession(authOptions)
    console.log(" Session récupérée:", {
      hasSession: !!session,
      role: session?.user?.role,
      userId: session?.user?.id
    })

    if (!session || session.user.role !== "SELLER") {
      console.log("❌ Erreur d'autorisation:", {
        hasSession: !!session,
        role: session?.user?.role
      })
      return NextResponse.json(
        { error: "Non autorisé - Accès vendeur requis" },
        { status: 401 }
      )
    }

    // Attendre les params avant d'accéder à leurs propriétés
    const resolvedParams = await params
    console.log(" Params récupérés:", resolvedParams)

    const projectId = parseInt(resolvedParams.id)
    console.log(" ID du projet:", { original: resolvedParams.id, parsed: projectId, isValid: !isNaN(projectId) })

    if (isNaN(projectId)) {
      console.log("❌ ID de projet invalide")
      return NextResponse.json(
        { error: "ID de projet invalide" },
        { status: 400 }
      )
    }

    // Convertir l'ID utilisateur de string vers number
    const userId = parseInt(session.user.id)
    console.log(" ID utilisateur:", { original: session.user.id, parsed: userId, isValid: !isNaN(userId) })

    if (isNaN(userId)) {
      console.log("❌ ID utilisateur invalide")
      return NextResponse.json(
        { error: "ID utilisateur invalide" },
        { status: 400 }
      )
    }

    // Vérifier que le vendeur existe
    const seller = await prisma.seller.findUnique({
      where: { userId: userId }
    })
    console.log(" Vendeur trouvé:", {
      found: !!seller,
      sellerId: seller?.id,
      businessName: seller?.business_name
    })

    if (!seller) {
      console.log("❌ Profil vendeur non trouvé")
      return NextResponse.json(
        { error: "Profil vendeur non trouvé" },
        { status: 404 }
      )
    }

    // Vérifier que le projet existe et est disponible
    console.log(" Recherche du projet avec ID:", projectId)
    const project = await prisma.project.findUnique({
      where: { id: projectId },
      include: {
        client: true,
        proposals: {
          where: { sellerId: seller.id }
        }
      }
    })

    console.log(" Projet récupéré:", {
      found: !!project,
      id: project?.id,
      title: project?.title,
      status: project?.status,
      clientId: project?.clientId,
      existingProposalsCount: project?.proposals?.length || 0
    })

    if (!project) {
      console.log("❌ Projet non trouvé")
      return NextResponse.json(
        { error: "Projet non trouvé" },
        { status: 404 }
      )
    }

    // Vérifier que le projet est en attente de propositions
    console.log(" Vérification du statut du projet:", {
        currentStatus: project.status,
        isPending: project.status === "pending",
        isOpen: project.status === "open",
        isOPEN: project.status === "OPEN",
        isPENDING: project.status === "PENDING"
    })

    if (project.status !== "pending" && project.status !== "open") {
      console.log("❌ Statut du projet invalide:", project.status)
      return NextResponse.json(
        { error: "Ce projet n'accepte plus de nouvelles propositions" },
        { status: 400 }
      )
    }

    // Vérifier que le vendeur n'a pas déjà fait une proposition
    console.log(" Vérification des propositions existantes:", {
      proposalsCount: project.proposals.length,
      hasExistingProposal: project.proposals.length > 0
    })

    if (project.proposals.length > 0) {
      console.log("❌ Proposition déjà existante")
      return NextResponse.json(
        { error: "Vous avez déjà soumis une proposition pour ce projet" },
        { status: 400 }
      )
    }

    // Récupérer les données du formulaire
    const body = await request.json()
    console.log(" Données reçues:", {
      hasPrice: !!body.price,
      priceValue: body.price,
      hasMessage: !!body.message,
      messageLength: body.message?.length,
      hasAdvertId: !!body.advertId
    })

    const { price, message, advertId } = body

    // Validation des données
    if (!price || !message) {
      console.log("❌ Données manquantes:", { hasPrice: !!price, hasMessage: !!message })
      return NextResponse.json(
        { error: "Le prix et le message sont obligatoires" },
        { status: 400 }
      )
    }

    const proposalPrice = parseFloat(price)
    console.log(" Prix analysé:", {
      original: price,
      parsed: proposalPrice,
      isValid: !isNaN(proposalPrice) && proposalPrice > 0
    })

    if (isNaN(proposalPrice) || proposalPrice <= 0) {
      console.log("❌ Prix invalide")
      return NextResponse.json(
        { error: "Le prix doit être un nombre positif" },
        { status: 400 }
      )
    }

    if (message.trim().length < 10) {
      console.log("❌ Message trop court:", message.trim().length)
      return NextResponse.json(
        { error: "Le message doit contenir au moins 10 caractères" },
        { status: 400 }
      )
    }

    console.log("✅ Toutes les validations passées, création de l'annonce...")

    // Gestion de l'annonce pour la proposition
    let advert = null

    if (advertId) {
      // Si un advertId est fourni, vérifier qu'il appartient au vendeur
      advert = await prisma.advert.findFirst({
        where: {
          id: parseInt(advertId),
          sellerId: seller.id,
          status: "active"
        }
      })

      if (!advert) {
        return NextResponse.json(
          { error: "Annonce non trouvée ou inactive" },
          { status: 404 }
        )
      }
    } else {
      // Créer une annonce simple pour cette proposition
      // Ne pas lier au projet pour éviter les contraintes
      advert = await prisma.advert.create({
        data: {
          title: `Proposition pour: ${project.title}`,
          description: message,
          price: proposalPrice,
          sellerId: seller.id,
          status: "active"
          // Pas de projectId pour éviter la contrainte unique
        }
      })
    }

    // Créer la proposition
    const proposal = await prisma.proposal.create({
      data: {
        price: proposalPrice,
        message: message.trim(),
        projectId: projectId,
        sellerId: seller.id,
        advertId: advert.id,
        status: "pending"
      },
      include: {
        seller: {
          include: {
            user: true
          }
        },
        project: {
          include: {
            client: true
          }
        }
      }
    })

    // Créer une notification pour le client
    await prisma.notification.create({
      data: {
        content: `Nouvelle proposition reçue pour votre projet "${project.title}" de ${seller.business_name}`,
        userId: project.client.userId,
        readStatus: false
      }
    })

    return NextResponse.json({
      success: true,
      message: "Proposition soumise avec succès !",
      proposal: {
        id: proposal.id,
        price: proposal.price,
        message: proposal.message,
        status: proposal.status,
        created_at: proposal.created_at,
        seller: {
          id: proposal.seller.id,
          business_name: proposal.seller.business_name,
          user: {
            username: proposal.seller.user.username
          }
        }
      }
    })

  } catch (error) {
    console.error("Erreur lors de la création de la proposition:", error)
    return NextResponse.json(
      { error: "Erreur interne du serveur" },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from "next/server"
import { getServerSession } from "next-auth/next"
import { authOptions } from "@/lib/auth"
import { prisma } from "@/lib/prisma"

export async function POST(
  request: NextRequest,
  { params }: { params: { id: string } }
) {
  try {
    console.log(" Début de la création de proposition")

    const session = await getServerSession(authOptions)
    console.log(" Session récupérée:", {
      hasSession: !!session,
      role: session?.user?.role,
      userId: session?.user?.id
    })

    if (!session || session.user.role !== "SELLER") {
      console.log("❌ Erreur d'autorisation:", {
        hasSession: !!session,
        role: session?.user?.role
      })
      return NextResponse.json(
        { error: "Non autorisé - Accès vendeur requis" },
        { status: 401 }
      )
    }

    // Attendre les params avant d'accéder à leurs propriétés
    const resolvedParams = await params
    console.log(" Params récupérés:", resolvedParams)

    const projectId = parseInt(resolvedParams.id)
    console.log(" ID du projet:", { original: resolvedParams.id, parsed: projectId, isValid: !isNaN(projectId) })

    if (isNaN(projectId)) {
      console.log("❌ ID de projet invalide")
      return NextResponse.json(
        { error: "ID de projet invalide" },
        { status: 400 }
      )
    }

    // Convertir l'ID utilisateur de string vers number
    const userId = parseInt(session.user.id)
    console.log(" ID utilisateur:", { original: session.user.id, parsed: userId, isValid: !isNaN(userId) })

    if (isNaN(userId)) {
      console.log("❌ ID utilisateur invalide")
      return NextResponse.json(
        { error: "ID utilisateur invalide" },
        { status: 400 }
      )
    }

    // Vérifier que le vendeur existe
    const seller = await prisma.seller.findUnique({
      where: { userId: userId }
    })
    console.log(" Vendeur trouvé:", {
      found: !!seller,
      sellerId: seller?.id,
      businessName: seller?.business_name
    })

    if (!seller) {
      console.log("❌ Profil vendeur non trouvé")
      return NextResponse.json(
        { error: "Profil vendeur non trouvé" },
        { status: 404 }
      )
    }

    // Vérifier que le projet existe et est disponible
    console.log(" Recherche du projet avec ID:", projectId)
    const project = await prisma.project.findUnique({
      where: { id: projectId },
      include: {
        client: true,
        proposals: {
          where: { sellerId: seller.id }
        }
      }
    })

    console.log(" Projet récupéré:", {
      found: !!project,
      id: project?.id,
      title: project?.title,
      status: project?.status,
      clientId: project?.clientId,
      existingProposalsCount: project?.proposals?.length || 0
    })

    if (!project) {
      console.log("❌ Projet non trouvé")
      return NextResponse.json(
        { error: "Projet non trouvé" },
        { status: 404 }
      )
    }

    // Vérifier que le projet est en attente de propositions
    console.log(" Vérification du statut du projet:", {
        currentStatus: project.status,
        isPending: project.status === "pending",
        isOpen: project.status === "open",
        isOPEN: project.status === "OPEN",
        isPENDING: project.status === "PENDING"
    })

    // Accepter différentes variations de statut (majuscules et minuscules)
    const validStatuses = ["pending", "open", "PENDING", "OPEN"]
    if (!validStatuses.includes(project.status)) {
      console.log("❌ Statut du projet invalide:", project.status)
      return NextResponse.json(
        { error: "Ce projet n'accepte plus de nouvelles propositions" },
        { status: 400 }
      )
    }

    // Vérifier que le vendeur n'a pas déjà fait une proposition
    console.log(" Vérification des propositions existantes:", {
      proposalsCount: project.proposals.length,
      hasExistingProposal: project.proposals.length > 0
    })

    if (project.proposals.length > 0) {
      console.log("❌ Proposition déjà existante")
      return NextResponse.json(
        { error: "Vous avez déjà soumis une proposition pour ce projet" },
        { status: 400 }
      )
    }

    // Récupérer les données du formulaire
    const body = await request.json()
    console.log(" Données reçues:", {
      hasPrice: !!body.price,
      priceValue: body.price,
      hasMessage: !!body.message,
      messageLength: body.message?.length,
      hasAdvertId: !!body.advertId
    })

    const { price, message, advertId } = body

    // Validation des données
    if (!price || !message) {
      console.log("❌ Données manquantes:", { hasPrice: !!price, hasMessage: !!message })
      return NextResponse.json(
        { error: "Le prix et le message sont obligatoires" },
        { status: 400 }
      )
    }

    const proposalPrice = parseFloat(price)
    console.log(" Prix analysé:", {
      original: price,
      parsed: proposalPrice,
      isValid: !isNaN(proposalPrice) && proposalPrice > 0
    })

    if (isNaN(proposalPrice) || proposalPrice <= 0) {
      console.log("❌ Prix invalide")
      return NextResponse.json(
        { error: "Le prix doit être un nombre positif" },
        { status: 400 }
      )
    }

    if (message.trim().length < 10) {
      console.log("❌ Message trop court:", message.trim().length)
      return NextResponse.json(
        { error: "Le message doit contenir au moins 10 caractères" },
        { status: 400 }
      )
    }

    console.log("✅ Toutes les validations passées, création de l'annonce...")

    // Gestion de l'annonce pour la proposition
    let advert = null

    if (advertId) {
      // Si un advertId est fourni, vérifier qu'il appartient au vendeur
      advert = await prisma.advert.findFirst({
        where: {
          id: parseInt(advertId),
          sellerId: seller.id,
          status: "active"
        }
      })

      if (!advert) {
        return NextResponse.json(
          { error: "Annonce non trouvée ou inactive" },
          { status: 404 }
        )
      }
    } else {
      // Créer une annonce simple pour cette proposition
      // Ne pas lier au projet pour éviter les contraintes
      advert = await prisma.advert.create({
        data: {
          title: `Proposition pour: ${project.title}`,
          description: message,
          price: proposalPrice,
          sellerId: seller.id,
          status: "active"
          // Pas de projectId pour éviter la contrainte unique
        }
      })
    }

    // Créer la proposition
    const proposal = await prisma.proposal.create({
      data: {
        price: proposalPrice,
        message: message.trim(),
        projectId: projectId,
        sellerId: seller.id,
        advertId: advert.id,
        status: "pending"
      },
      include: {
        seller: {
          include: {
            user: true
          }
        },
        project: {
          include: {
            client: true
          }
        }
      }
    })

    // Créer une notification pour le client
    await prisma.notification.create({
      data: {
        content: `Nouvelle proposition reçue pour votre projet "${project.title}" de ${seller.business_name}`,
        userId: project.client.userId,
        readStatus: false
      }
    })

    return NextResponse.json({
      success: true,
      message: "Proposition soumise avec succès !",
      proposal: {
        id: proposal.id,
        price: proposal.price,
        message: proposal.message,
        status: proposal.status,
        created_at: proposal.created_at,
        seller: {
          id: proposal.seller.id,
          business_name: proposal.seller.business_name,
          user: {
            username: proposal.seller.user.username
          }
        }
      }
    })

  } catch (error) {
    console.error("Erreur lors de la création de la proposition:", error)
    return NextResponse.json(
      { error: "Erreur interne du serveur" },
      { status: 500 }
    )
  }
}

"use client"

import type React from "react"

import { useState } from "react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import { signIn } from "next-auth/react"
import { Eye, EyeOff } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Checkbox } from "@/components/ui/checkbox"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { toast } from "@/hooks/use-toast"

export default function RegisterPage() {
  const router = useRouter()
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [userType, setUserType] = useState("customer")
  const [tailorType, setTailorType] = useState("individual")
  const [isLoading, setIsLoading] = useState(false)

  const [customerFormData, setCustomerFormData] = useState({
    fullName: "",
    email: "",
    phoneNumber: "",
    address: "",
    postalCode: "",
    password: "",
    confirmPassword: "",
    agreeTerms: false,
    receiveAlerts: false,
  })

  const [individualTailorFormData, setIndividualTailorFormData] = useState({
    profileName: "",
    fullName: "",
    email: "",
    phoneNumber: "",
    servicesOffered: "",
    yearsOfExperience: "",
    password: "",
    confirmPassword: "",
    agreeTerms: false,
    receiveAlerts: false,
  })

  const [professionalTailorFormData, setProfessionalTailorFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    password: "",
    confirmPassword: "",
    companyName: "",
    companyType: "",
    siretNumber: "",
    address: "",
    city: "",
    postalCode: "",
    country: "",
    companyPhoneNumber: "",
    servicesOffered: "",
    agreeTerms: false,
    receiveAlerts: false,
  })

  const handleCustomerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setCustomerFormData((prev) => ({ ...prev, [name]: value }))
  }

  const handleIndividualTailorChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setIndividualTailorFormData((prev) => ({ ...prev, [name]: value }))
  }

  const handleProfessionalTailorChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setProfessionalTailorFormData((prev) => ({ ...prev, [name]: value }))
  }

  const handleCustomerCheckboxChange = (name: string, checked: boolean) => {
    setCustomerFormData((prev) => ({ ...prev, [name]: checked }))
  }

  const handleIndividualTailorCheckboxChange = (name: string, checked: boolean) => {
    setIndividualTailorFormData((prev) => ({ ...prev, [name]: checked }))
  }

  const handleProfessionalTailorCheckboxChange = (name: string, checked: boolean) => {
    setProfessionalTailorFormData((prev) => ({ ...prev, [name]: checked }))
  }

  const handleCustomerSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)

    if (customerFormData.password !== customerFormData.confirmPassword) {
      toast({
        title: "Erreur",
        description: "Les mots de passe ne correspondent pas",
        variant: "destructive",
      })
      setIsLoading(false)
      return
    }

    try {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: customerFormData.email,
          username: customerFormData.email.split("@")[0],
          password: customerFormData.password,
          role: "CLIENT",
          firstname: customerFormData.fullName.split(" ")[0],
          lastname: customerFormData.fullName.split(" ").slice(1).join(" "),
          phoneNumber: customerFormData.phoneNumber,
          address: customerFormData.address,
          postalCode: customerFormData.postalCode,
          agreeTerms: customerFormData.agreeTerms,
          receiveAlerts: customerFormData.receiveAlerts,
        }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.message || "Une erreur est survenue lors de l'inscription")
      }

      toast({
        title: "Inscription réussie",
        description: "Votre compte a été créé avec succès",
      })

      // Connecter automatiquement l'utilisateur
      const result = await signIn("credentials", {
        email: customerFormData.email,
        password: customerFormData.password,
        redirect: false,
      })

      if (result?.ok) {
        router.push("/client/account")
      }
    } catch (error: any) {
      toast({
        title: "Erreur d'inscription",
        description: error.message,
        variant: "destructive",
      })
    } finally {
      setIsLoading(false)
    }
  }

  const handleIndividualTailorSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)

    if (individualTailorFormData.password !== individualTailorFormData.confirmPassword) {
      toast({
        title: "Erreur",
        description: "Les mots de passe ne correspondent pas",
        variant: "destructive",
      })
      setIsLoading(false)
      return
    }

    try {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: individualTailorFormData.email,
          username: individualTailorFormData.email.split("@")[0],
          password: individualTailorFormData.password,
          role: "SELLER",
          business_name: individualTailorFormData.profileName,
          fullName: individualTailorFormData.fullName,
          phoneNumber: individualTailorFormData.phoneNumber,
          servicesOffered: individualTailorFormData.servicesOffered,
          yearsOfExperience: individualTailorFormData.yearsOfExperience,
          agreeTerms: individualTailorFormData.agreeTerms,
          receiveAlerts: individualTailorFormData.receiveAlerts,
        }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.message || "Une erreur est survenue lors de l'inscription")
      }

      toast({
        title: "Inscription réussie",
        description: "Votre compte a été créé avec succès",
      })

      // Connecter automatiquement l'utilisateur
      const result = await signIn("credentials", {
        email: individualTailorFormData.email,
        password: individualTailorFormData.password,
        redirect: false,
      })

      if (result?.ok) {
        router.push("/seller/dashboard")
      }
    } catch (error: any) {
      toast({
        title: "Erreur d'inscription",
        description: error.message,
        variant: "destructive",
      })
    } finally {
      setIsLoading(false)
    }
  }

  const handleProfessionalTailorSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)

    if (professionalTailorFormData.password !== professionalTailorFormData.confirmPassword) {
      toast({
        title: "Erreur",
        description: "Les mots de passe ne correspondent pas",
        variant: "destructive",
      })
      setIsLoading(false)
      return
    }

    try {
      const response = await fetch("/api/auth/register", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email: professionalTailorFormData.email,
          username: professionalTailorFormData.email.split("@")[0],
          password: professionalTailorFormData.password,
          role: "SELLER",
          business_name: professionalTailorFormData.companyName,
          fullName: `${professionalTailorFormData.firstName} ${professionalTailorFormData.lastName}`.trim(),
          companyType: professionalTailorFormData.companyType,
          siretNumber: professionalTailorFormData.siretNumber,
          companyAddress: professionalTailorFormData.address,
          companyCity: professionalTailorFormData.city,
          companyPostalCode: professionalTailorFormData.postalCode,
          companyCountry: professionalTailorFormData.country,
          companyPhoneNumber: professionalTailorFormData.companyPhoneNumber,
          agreeTerms: professionalTailorFormData.agreeTerms,
          receiveAlerts: professionalTailorFormData.receiveAlerts,
        }),
      })

      const data = await response.json()

      if (!response.ok) {
        throw new Error(data.message || "Une erreur est survenue lors de l'inscription")
      }

      toast({
        title: "Inscription réussie",
        description: "Votre compte a été créé avec succès",
      })

      // Connecter automatiquement l'utilisateur
      const result = await signIn("credentials", {
        email: professionalTailorFormData.email,
        password: professionalTailorFormData.password,
        redirect: false,
      })

      if (result?.ok) {
        router.push("/seller/dashboard")
      }
    } catch (error: any) {
      toast({
        title: "Erreur d'inscription",
        description: error.message,
        variant: "destructive",
      })
    } finally {
      setIsLoading(false)
    }
  }

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword)
  }

  const toggleConfirmPasswordVisibility = () => {
    setShowConfirmPassword(!showConfirmPassword)
  }

  return (
      <div className="flex min-h-screen items-center justify-center bg-gray-50 py-12 px-4 sm:px-6 lg:px-8">
        <div className="w-full max-w-md space-y-8 bg-white p-8 rounded-lg shadow-md">
          <div className="flex justify-between items-center">
            <Tabs defaultValue="customer" onValueChange={setUserType} className="w-full">
              <TabsList className="grid w-full grid-cols-2 mb-6">
                <TabsTrigger value="customer">Join as Customer</TabsTrigger>
                <TabsTrigger value="tailor">Join as Tailor</TabsTrigger>
              </TabsList>

              {/* Customer Registration Form */}
              <TabsContent value="customer">
                <h2 className="text-xl font-bold text-gray-900 mb-6">Join as Customer</h2>
                <form className="space-y-4" onSubmit={handleCustomerSubmit}>
                  <div>
                    <label htmlFor="customer-fullName" className="block text-sm font-medium text-gray-700 mb-1">
                      Full Name
                    </label>
                    <Input
                        id="customer-fullName"
                        name="fullName"
                        type="text"
                        required
                        placeholder="John Doe"
                        value={customerFormData.fullName}
                        onChange={handleCustomerChange}
                        disabled={isLoading}
                    />
                  </div>

                  <div>
                    <label htmlFor="customer-email" className="block text-sm font-medium text-gray-700 mb-1">
                      Email
                    </label>
                    <Input
                        id="customer-email"
                        name="email"
                        type="email"
                        required
                        placeholder="mail@email.com"
                        value={customerFormData.email}
                        onChange={handleCustomerChange}
                        disabled={isLoading}
                    />
                  </div>

                  <div>
                    <label htmlFor="customer-phoneNumber" className="block text-sm font-medium text-gray-700 mb-1">
                      Phone number
                    </label>
                    <Input
                        id="customer-phoneNumber"
                        name="phoneNumber"
                        type="tel"
                        required
                        placeholder="00 00 00 00 00"
                        value={customerFormData.phoneNumber}
                        onChange={handleCustomerChange}
                        disabled={isLoading}
                    />
                  </div>

                  <div>
                    <label htmlFor="customer-address" className="block text-sm font-medium text-gray-700 mb-1">
                      Address
                    </label>
                    <Input
                        id="customer-address"
                        name="address"
                        type="text"
                        required
                        placeholder="123 Lamplight Parade"
                        value={customerFormData.address}
                        onChange={handleCustomerChange}
                        disabled={isLoading}
                    />
                  </div>

                  <div>
                    <label htmlFor="customer-postalCode" className="block text-sm font-medium text-gray-700 mb-1">
                      Postal Code
                    </label>
                    <Input
                        id="customer-postalCode"
                        name="postalCode"
                        type="text"
                        required
                        placeholder="75001"
                        value={customerFormData.postalCode}
                        onChange={handleCustomerChange}
                        disabled={isLoading}
                    />
                  </div>

                  <div>
                    <label htmlFor="customer-password" className="block text-sm font-medium text-gray-700 mb-1">
                      Password
                    </label>
                    <div className="relative">
                      <Input
                          id="customer-password"
                          name="password"
                          type={showPassword ? "text" : "password"}
                          required
                          placeholder="••••••••••••"
                          value={customerFormData.password}
                          onChange={handleCustomerChange}
                          disabled={isLoading}
                      />
                      <button
                          type="button"
                          className="absolute inset-y-0 right-0 pr-3 flex items-center"
                          onClick={togglePasswordVisibility}
                      >
